public class Main {
    public static void main(String[] args) {
        int cookies = 17;
        int kids = 5;
        int each = cookies / kids;
        int left = cookies % kids;
        System.out.println("Each kid gets: " + each);
        System.out.println("Left over: " + left);
        System.out.println("Handed out: " + (cookies - left));
        System.out.println("Check: " + (each * kids + left));
        System.out.println("-7 / 2 = " + (-7 / 2));
        System.out.println("-7 % 3 = " + (-7 % 3));
    }
}

