public class Main {
    public static void main(String[] args) {
        int balance = 100;
        balance += 50;
        System.out.println("After deposit: " + balance);
        balance -= 30;
        System.out.println("After withdrawal: " + balance);

        int visits = 0;
        visits++;
        visits++;
        int old = visits++;
        System.out.println("visits++ gave " + old + ", visits is now " + visits);
        int fresh = ++visits;
        System.out.println("++visits gave " + fresh);
        visits--;
        System.out.println("After visits--: " + visits);

        int x = 5;
        x *= 1.5;
        System.out.println("After x *= 1.5: " + x);
        x %= 4;
        System.out.println("After x %= 4: " + x);
        System.out.println(2 + 3 * 4);
        System.out.println((2 + 3) * 4);
    }
}

