practice.solution:
public class Main {
    public static void main(String[] args) {
        int score = 40;
        int level = 1;
        score += 25;
        System.out.println("After bonus: " + score);
        score *= 1.5;
        System.out.println("After combo: " + score);
        score -= 12;
        System.out.println("After hit: " + score);
        score /= 2;
        System.out.println("After halving: " + score);
        int oldLevel = level++;
        System.out.println("Level: " + oldLevel + " -> " + level);
    }
}
